import java.util.*;public class Policy {private final int capacity;private final Map<String,Deque<String>> entries=new HashMap<>();public Policy(int capacity){if(capacity<1)throw new IllegalArgumentException();this.capacity=capacity;}public void append(String player,String command){var list=entries.computeIfAbsent(player,key->new ArrayDeque<>());list.addLast(command);while(list.size()>capacity)list.removeFirst();}public List<String> history(String player){return List.copyOf(entries.getOrDefault(player,new ArrayDeque<>()));}}
